---
     1	const DAY = 24 * 60 * 60 * 1000;
     2	
     3	// Credit for the unused part of a billing period when a plan changes.
     4	export function prorate(price, periodStart, periodEnd, changedAt) {
     5	  const total = Math.round((periodEnd - periodStart) / DAY);
     6	  const unused = Math.round((periodEnd - changedAt) / DAY);
     7	  return price * unused / total;
     8	}
