     6	  const start = Date.UTC(2026, 10, 1);
     7	  const end = Date.UTC(2026, 11, 1);
     8	  const changed = Date.UTC(2026, 10, 16);
     9	  assert.equal(prorate(30, start, end, changed), 15);
